/* @autogenerated */
import { TestBed } from '@angular/core/testing';
import { TranslocoTestingModule } from '@jsverse/transloco';
import { EditableMarkdownComponent } from './editable-markdown.component';

/** Editor.js falso: guarda la configuración y los bloques que se le pintan. */
class FakeEditor {
  static last: FakeEditor;
  rendered: any[] = [];
  saved: any = { blocks: [] };
  constructor(readonly config: any) {
    FakeEditor.last = this;
  }
  save() {
    return Promise.resolve(this.saved);
  }
  render(data: any) {
    this.rendered.push(data);
  }
}

/** markdown-it falso: devuelve el HTML que se le indique. */
let html = '';
function fakeMarkdownIt(this: any) {
  this.render = () => html;
}

const settle = () => new Promise((resolve) => setTimeout(resolve));

describe('EditableMarkdownComponent', () => {
  const statics = EditableMarkdownComponent as any;
  const globals = ['EditorJS', 'Header', 'Paragraph', 'EditorjsList', 'Quote', 'CodeTool', 'markdownit'];
  let appended: HTMLScriptElement[];

  const create = () => {
    const fixture = TestBed.createComponent(EditableMarkdownComponent);
    fixture.detectChanges();
    return fixture;
  };

  beforeEach(() => {
    statics.assetsLoaded = false;
    statics.loadPromise = null;
    Object.assign(window, { EditorJS: FakeEditor, markdownit: fakeMarkdownIt });
    appended = [];
    // Los scripts del editor no se descargan: cada uno "carga" al añadirse
    const append = document.body.appendChild.bind(document.body);
    spyOn(document.body, 'appendChild').and.callFake(<T extends Node>(node: T): T => {
      if (node instanceof HTMLScriptElement) {
        appended.push(node);
        setTimeout(() => node.onload?.(new Event('load')));
        return node;
      }
      return append(node);
    });
    TestBed.configureTestingModule({
      imports: [EditableMarkdownComponent, TranslocoTestingModule.forRoot({ langs: { en: {} } })],
    });
  });

  afterEach(() => {
    TestBed.resetTestingModule();
    globals.forEach((name) => delete (window as any)[name]);
    statics.assetsLoaded = false;
    statics.loadPromise = null;
  });

  it('loads the editor scripts once from its assets path', async () => {
    create();
    await settle();

    expect(appended.map((script) => script.src.replace(/^.*\/assets/, '/assets'))).toEqual([
      '/assets/editorjs/editor.min.js',
      '/assets/editorjs/header.js',
      '/assets/editorjs/paragraph.js',
      '/assets/editorjs/list.js',
      '/assets/editorjs/quote.js',
      '/assets/editorjs/code.js',
      '/assets/editorjs/markdown-it.min.js',
    ]);
    expect(statics.assetsLoaded).toBeTrue();

    create();
    await settle();
    expect(appended.length).toBe(7);
  });

  it('shares the loading in progress', async () => {
    const fixture = create();
    const pending = statics.loadPromise;
    expect(pending).toBeTruthy();

    expect((fixture.componentInstance as any).loadEditorAssets()).toBe(pending);
  });

  it('fails the loading when a script can not be loaded', async () => {
    const component = TestBed.createComponent(EditableMarkdownComponent).componentInstance as any;
    (document.body.appendChild as jasmine.Spy).and.callFake((node: any) => {
      setTimeout(() => node.onerror?.(new Event('error')));
      return node;
    });

    await expectAsync(component.loadEditorAssets()).toBeRejectedWith(jasmine.stringMatching('Failed to load'));
  });

  it('creates the editor in its container and shows the current value when ready', async () => {
    html = '<h2>Title</h2>';
    const fixture = create();
    fixture.componentInstance.writeValue('## Title');
    await settle();

    const editor = FakeEditor.last;
    expect(editor.config.holder).toBe(fixture.componentInstance.editorRef()!.nativeElement);
    editor.config.onReady();
    await settle();

    expect(editor.rendered[0].blocks).toEqual([{ type: 'header', data: { text: 'Title', level: 2 } }]);
  });

  it('writes the markdown of the editor content on each change', async () => {
    const fixture = create();
    const changes: (string | null)[] = [];
    fixture.componentInstance.registerOnChange((value: string | null) => changes.push(value));
    await settle();
    const editor = FakeEditor.last;
    editor.saved = { blocks: [{ type: 'paragraph', data: { text: 'Hello' } }] };

    await editor.config.onChange();

    expect(changes).toEqual(['Hello\n']);
  });

  it('renders again when the value changes from outside', async () => {
    const fixture = create();
    await settle();
    const editor = FakeEditor.last;
    html = '<p>Other</p>';

    fixture.componentInstance.writeValue('Other');
    fixture.detectChanges();
    await settle();

    expect(editor.rendered.at(-1).blocks).toEqual([{ type: 'paragraph', data: { text: 'Other' } }]);
  });

  it('turns editor blocks into markdown', () => {
    const component = TestBed.createComponent(EditableMarkdownComponent).componentInstance as any;

    const markdown = component.editorDataToMarkdown({
      blocks: [
        { type: 'header', data: { level: 3, text: 'Title' } },
        { type: 'paragraph', data: { text: 'Text' } },
        { type: 'list', data: { style: 'ordered', items: ['<b>one</b>', { content: 'two' }, { text: 'three' }, {}] } },
        { type: 'list', data: { style: 'unordered', items: ['dot'] } },
        { type: 'quote', data: { text: 'Said' } },
        { type: 'code', data: { code: 'let a = 1;' } },
        { type: 'image', data: { caption: 'Logo', file: { url: 'logo.png' } } },
        { type: 'image', data: {} },
        { type: 'table', data: {} },
      ],
    });

    expect(markdown.split('\n').filter((line: string) => line)).toEqual([
      '### Title',
      'Text',
      '1. one',
      '1. two',
      '1. three',
      '1. ',
      '- dot',
      '> Said',
      '```',
      'let a = 1;',
      '```',
      '![Logo](logo.png)',
      '![]()',
      '<!-- bloque no reconocido: table -->',
    ]);
  });

  it('turns markdown into editor blocks', async () => {
    const component = TestBed.createComponent(EditableMarkdownComponent).componentInstance as any;
    html =
      '<h1>Title</h1><p>Text</p><ul><li>a</li></ul><ol><li>b</li></ol>' +
      '<blockquote>Said</blockquote><pre><code> code </code></pre><img src="logo.png" alt="Logo"><img src="x.png">';

    const data = await component.markdownToEditorData('ignored');

    expect(data.blocks).toEqual([
      { type: 'header', data: { text: 'Title', level: 1 } },
      { type: 'paragraph', data: { text: 'Text' } },
      { type: 'list', data: { style: 'unordered', items: ['a'] } },
      { type: 'list', data: { style: 'ordered', items: ['b'] } },
      { type: 'quote', data: { text: 'Said', caption: '', alignment: 'left' } },
      { type: 'code', data: { code: 'code' } },
      jasmine.objectContaining({ type: 'image', data: jasmine.objectContaining({ caption: 'Logo' }) }),
      jasmine.objectContaining({ type: 'image', data: jasmine.objectContaining({ caption: '' }) }),
    ]);
  });
});
